if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['retry_id'])){verify_csrf();if(srms_consume_operation($dbh,'notification.retry')){$id=(int)$_POST['retry_id'];$q=$dbh->prepare("UPDATE notification_queue SET status='queued',attempts=0,last_error=NULL WHERE id=:id AND status IN ('failed','skipped')");$q->execute([':id'=>$id]);audit_log($dbh,'NOTIFICATION_RETRY','Queue item '.$id);}header('Location: notification-delivery.php');exit;}
$filter=trim($_GET['status']??'');$sql='SELECT n.*,s.StudentName FROM notification_queue n LEFT JOIN tblstudents s ON s.StudentId=n.student_id';$params=[];if(in_array($filter,['queued','sent','failed','skipped'],true)){$sql.=' WHERE n.status=:st';$params[':st']=$filter;}$sql.=' ORDER BY n.id DESC LIMIT 300';$q=$dbh->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notification Delivery | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid"><h2>Guardian Notification Delivery</h2><p>Email and WhatsApp notifications are queued when approved results are published. A server-side worker must be configured to deliver them.</p><form method="get" class="form-inline"><label>Status&nbsp;</label><select name="status" class="form-control"><option value="">All</option><?php foreach(['queued','sent','failed','skipped'] as $st):?><option <?=$filter===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select> <button class="btn btn-primary">Filter</button></form><div class="table-responsive" style="margin-top:15px"><table class="table table-bordered table-striped"><thead><tr><th>Date</th><th>Student</th><th>Channel</th><th>Recipient</th><th>Period</th><th>Status</th><th>Attempts / Error</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['StudentName']??'Unknown')?></td><td><?=e(strtoupper($r['channel']))?></td><td><?=e($r['recipient'])?></td><td><?=e($r['academic_year'].' / '.$r['term'].' / '.$r['exam_type'])?></td><td><?=e($r['status'])?></td><td><?= (int)$r['attempts']?> <?=e($r['last_error']??'')?></td><td><?php if(in_array($r['status'],['failed','skipped'],true)):?><form method="post"><?=csrf_field()?><?=srms_operation_field('notification.retry')?><input type="hidden" name="retry_id" value="<?=$r['id']?>"><button class="btn btn-xs btn-warning">Retry</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">No notifications found.</td></tr><?php endif;?></tbody></table></div></div></main></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
